// Medical image generation — Google "Nano Banana" (Gemini native image) via
// the Interactions API, with a legacy generateContent fallback for older keys.
//
// Generated bytes are stored in Cloudflare R2 and served through
// /api/ai-image?img=<id>. When R2 is not configured (local dev) the base64
// data URL is returned directly so the feature still works.
//
// This module deliberately uses the existing Gemini key pool + cooldown state
// from ai-providers.server.ts, so image calls share quota accounting and key
// rotation with text calls.

import { PutObjectCommand, GetObjectCommand, S3Client } from "@aws-sdk/client-s3";
import {
  bumpDailyCounter,
  cool,
  coolModel,
  coolModelUntilUTCMidnight,
  hashKey,
  isKeyCooling,
  isModelCooling,
  keyRuntimeSnapshot,
  loadProvidersConfig,
  noteRequest,
} from "./ai-providers.server";

const INTERACTIONS_URL = "https://generativelanguage.googleapis.com/v1beta/interactions";
const GENERATE_URL = "https://generativelanguage.googleapis.com/v1beta/models";

// Newest first. The first model that the key has access to wins. Admins can
// override with GEMINI_IMAGE_MODEL="model-a,model-b".
const DEFAULT_IMAGE_MODELS = [
  "gemini-nano-banana-2.1",
  "gemini-3.1-flash-image",
  "gemini-3-pro-image",
  "gemini-2.5-flash-image",
];

const ALLOWED_ASPECTS = new Set([
  "1:1", "3:2", "2:3", "3:4", "4:3", "4:5", "5:4", "9:16", "16:9", "21:9",
]);

export type ImageKind =
  | "anatomy"
  | "mechanism"
  | "pathology"
  | "histology"
  | "radiology"
  | "clinical_photo"
  | "procedure"
  | "comparison"
  | "flowchart";

export type GenerateImageInput = {
  prompt: string;
  kind?: string;
  modality?: string;
  title?: string;
  aspect?: string;
  size?: string;
};

export type GenerateImageResult =
  | {
      ok: true;
      /** Relative URL served by /api/ai-image (preferred). */
      url?: string;
      /** Base64 data URL fallback when R2 is unavailable. */
      dataUrl?: string;
      mimeType: string;
      model: string;
      ms: number;
    }
  | { ok: false; reason: "no_key" | "busy" | "error"; message: string; status?: number };

type ImagePayload = { base64: string; mimeType: string };

type ApiCallResult =
  | { ok: true; payload: ImagePayload; ms: number }
  | { ok: false; status: number; message: string; ms: number };

function imageModels(): string[] {
  const configured = String(process.env.GEMINI_IMAGE_MODEL || "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return Array.from(new Set([...configured, ...DEFAULT_IMAGE_MODELS]));
}

function sanitizeAspect(aspect?: string): string {
  return aspect && ALLOWED_ASPECTS.has(aspect) ? aspect : "4:3";
}

function sanitizeSize(size?: string): "1K" | "2K" | "4K" {
  return size === "1K" || size === "2K" || size === "4K" ? size : "2K";
}

function supportsImageSize(model: string): boolean {
  // Gemini 2.5 Flash Image is 1K only.
  return !model.startsWith("gemini-2.5");
}

const KIND_STYLE: Record<ImageKind, string> = {
  anatomy:
    "Premium medical textbook anatomical plate. Clean warm-ivory background, accurate proportions, realistic tissue colour, fine leader lines and short English anatomical labels. Show the exact region and view named in the brief. No clutter, no decorative borders, no long paragraphs.",
  mechanism:
    "Clean scientific mechanism diagram in a modern textbook style. Show the causal sequence with bold directional arrows, numbered steps where useful, and short English labels for every molecule, cell, organ and pathway named in the brief. Neutral background, high contrast, no decorative elements.",
  pathology:
    "Medical pathology illustration that clearly contrasts normal versus abnormal structure. Accurate gross or microscopic appearance for the named disease, clean labels, restrained colour. Neutral background, no gore beyond what is medically necessary.",
  histology:
    "Photorealistic light-microscopy image. Use the named stain (H&E if unspecified), correct tissue architecture, sharp focus, realistic staining colour, and a small scale bar. No labels burned into the image unless the brief explicitly asks for arrows.",
  radiology:
    "Photorealistic radiological image. Match the exact modality named in the brief (CT, MRI, X-ray, ultrasound). Correct anatomical level, projection and side; realistic grayscale/window/contrast; black background. One image only, not a collage. Add at most 2-3 short labels or arrows for the key finding. No patient identifiers, no scanner branding.",
  clinical_photo:
    "Photorealistic, respectful clinical photograph for medical education. Neutral clinical background, natural lighting, sharp focus on the named sign or lesion. No identifiable face, no name badge, no gore, no sensational content. One image only.",
  procedure:
    "Step-by-step procedural illustration. If the brief contains multiple steps, use a clean multi-panel grid with numbered steps and short English labels; otherwise a single accurate procedural view. Sterile blue/white palette, realistic instruments, no gore.",
  comparison:
    "Side-by-side medical comparison panel with equal lighting, scale and framing. Label each side clearly in English. Neutral background, clean dividers, no decorative clutter.",
  flowchart:
    "Clean clinical flowchart / algorithm. Rounded boxes, logical arrows, short English labels, clear decision diamonds. Neutral background, high legibility, no long paragraphs.",
};

function normalizeKind(kind?: string): ImageKind {
  const k = String(kind || "").toLowerCase().replace(/[\s-]+/g, "_");
  if (k in KIND_STYLE) return k as ImageKind;
  if (k === "ct" || k === "mri" || k === "xray" || k === "x_ray" || k === "ultrasound") return "radiology";
  if (k === "photo" || k === "clinical" || k === "real_photo") return "clinical_photo";
  if (k === "diagram" || k === "illustration") return "anatomy";
  return "anatomy";
}

export function buildMedicalImagePrompt(input: GenerateImageInput): string {
  const kind = normalizeKind(input.kind);
  const modality = input.modality ? ` Modality: ${input.modality}.` : "";
  const title = input.title ? ` Subject: ${input.title}.` : "";
  return [
    "Create ONE high-quality medical education visual for a medical student. It must be immediately useful at a glance.",
    `Visual type: ${kind}.${modality}${title}`,
    `CONTENT BRIEF:\n${String(input.prompt || "").trim()}`,
    `STYLE:\n${KIND_STYLE[kind]}`,
    "ACCURACY: Use standard anatomy, pathology and medical terminology. Do not invent structures or findings. Every label must be spelled correctly and point to the correct structure. Keep labels short. No watermark, no signature, no patient identifiers, no UI chrome.",
    "SAFETY: Educational only. No gore, no identifiable faces, no sensational or misleading content.",
  ].join("\n\n");
}

// ---------------------------------------------------------------------------
// Response parsing

function parseErrorMessage(text: string): string {
  try {
    const json = JSON.parse(text) as { error?: { message?: string } | string; message?: string };
    if (typeof json.error === "string") return json.error;
    if (json.error?.message) return json.error.message;
    if (json.message) return json.message;
  } catch {
    // fall through
  }
  return text.slice(0, 400);
}

function asPayload(node: unknown): ImagePayload | null {
  if (!node || typeof node !== "object") return null;
  const o = node as Record<string, unknown>;
  const mime =
    (typeof o.mime_type === "string" && o.mime_type) ||
    (typeof o.mimeType === "string" && o.mimeType) ||
    (typeof o.mime === "string" && o.mime) ||
    "";
  const data =
    (typeof o.data === "string" && o.data) ||
    (typeof o.base64 === "string" && o.base64) ||
    (typeof o.image_data === "string" && o.image_data) ||
    "";
  if (data && mime.startsWith("image/")) return { base64: data, mimeType: mime };
  return null;
}

/** Recursively find the first inline image block in an API response. */
function extractImage(node: unknown, depth = 0): ImagePayload | null {
  if (!node || depth > 12) return null;
  if (Array.isArray(node)) {
    for (const item of node) {
      const found = extractImage(item, depth + 1);
      if (found) return found;
    }
    return null;
  }
  if (typeof node !== "object") return null;
  const o = node as Record<string, unknown>;

  const direct = asPayload(o);
  if (direct) return direct;

  for (const key of ["inline_data", "inlineData", "image", "output_image", "outputImage", "content", "parts", "steps"]) {
    if (o[key]) {
      const found = extractImage(o[key], depth + 1);
      if (found) return found;
    }
  }
  // Last-resort scan. Guarded to avoid walking huge unrelated structures too
  // deeply; image fields are normally shallow.
  for (const value of Object.values(o)) {
    const found = extractImage(value, depth + 1);
    if (found) return found;
  }
  return null;
}

async function readApiJson(resp: Response): Promise<{ ok: boolean; status: number; text: string; json: unknown }> {
  const text = await resp.text();
  let json: unknown = null;
  try { json = JSON.parse(text); } catch { /* not JSON */ }
  return { ok: resp.ok, status: resp.status, text, json };
}

async function callInteractions(
  key: string,
  model: string,
  prompt: string,
  aspect: string,
  size: string,
): Promise<ApiCallResult> {
  const t0 = Date.now();
  const mime = "image/png";
  const responseFormat: Record<string, unknown> = {
    type: "image",
    mime_type: mime,
    aspect_ratio: aspect,
  };
  if (supportsImageSize(model)) responseFormat.image_size = size;

  let resp: Response;
  try {
    resp = await fetch(INTERACTIONS_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-goog-api-key": key },
      body: JSON.stringify({
        model,
        input: [{ type: "text", text: prompt }],
        response_format: responseFormat,
      }),
      signal: typeof AbortSignal !== "undefined" && AbortSignal.timeout ? AbortSignal.timeout(120_000) : undefined,
    });
  } catch (e) {
    return { ok: false, status: 599, message: (e as Error).message || "Network error", ms: Date.now() - t0 };
  }
  const parsed = await readApiJson(resp);
  if (!parsed.ok) {
    return { ok: false, status: parsed.status, message: parseErrorMessage(parsed.text), ms: Date.now() - t0 };
  }
  const payload = extractImage(parsed.json);
  if (!payload) {
    return { ok: false, status: 502, message: "No image returned by the model", ms: Date.now() - t0 };
  }
  return { ok: true, payload, ms: Date.now() - t0 };
}

async function callGenerateContent(
  key: string,
  model: string,
  prompt: string,
  aspect: string,
): Promise<ApiCallResult> {
  const t0 = Date.now();
  const url = `${GENERATE_URL}/${encodeURIComponent(model)}:generateContent`;
  const body: Record<string, unknown> = {
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: {
      responseModalities: ["TEXT", "IMAGE"],
      imageConfig: { aspectRatio: aspect },
    },
  };

  let resp: Response;
  try {
    resp = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-goog-api-key": key },
      body: JSON.stringify(body),
      signal: typeof AbortSignal !== "undefined" && AbortSignal.timeout ? AbortSignal.timeout(120_000) : undefined,
    });
  } catch (e) {
    return { ok: false, status: 599, message: (e as Error).message || "Network error", ms: Date.now() - t0 };
  }
  const parsed = await readApiJson(resp);
  if (!parsed.ok) {
    // Some older image models reject imageConfig / responseModalities. Retry
    // once with a minimal body — the model's default output is an image.
    if (parsed.status === 400) {
      try {
        const retry = await fetch(url, {
          method: "POST",
          headers: { "Content-Type": "application/json", "x-goog-api-key": key },
          body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] }),
          signal: typeof AbortSignal !== "undefined" && AbortSignal.timeout ? AbortSignal.timeout(120_000) : undefined,
        });
        const retryParsed = await readApiJson(retry);
        if (retryParsed.ok) {
          const payload = extractImage(retryParsed.json);
          if (payload) return { ok: true, payload, ms: Date.now() - t0 };
          return { ok: false, status: 502, message: "No image returned by the model", ms: Date.now() - t0 };
        }
        return { ok: false, status: retryParsed.status, message: parseErrorMessage(retryParsed.text), ms: Date.now() - t0 };
      } catch (e) {
        return { ok: false, status: 599, message: (e as Error).message || "Network error", ms: Date.now() - t0 };
      }
    }
    return { ok: false, status: parsed.status, message: parseErrorMessage(parsed.text), ms: Date.now() - t0 };
  }
  const payload = extractImage(parsed.json);
  if (!payload) {
    return { ok: false, status: 502, message: "No image returned by the model", ms: Date.now() - t0 };
  }
  return { ok: true, payload, ms: Date.now() - t0 };
}

// ---------------------------------------------------------------------------
// R2 storage

function r2Client(): { client: S3Client; bucket: string } | null {
  const endpoint = process.env.R2_ENDPOINT;
  const accessKeyId = process.env.R2_ACCESS_KEY_ID;
  const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
  if (!endpoint || !accessKeyId || !secretAccessKey) return null;
  return {
    client: new S3Client({
      region: "auto",
      endpoint,
      forcePathStyle: true,
      credentials: { accessKeyId, secretAccessKey },
    }),
    bucket: process.env.R2_BUCKET_NAME || "curaq",
  };
}

function newImageId(): string {
  try {
    if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID().replace(/-/g, "");
  } catch { /* fall through */ }
  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 18)}`;
}

async function storeImage(payload: ImagePayload): Promise<{ id: string } | null> {
  const r2 = r2Client();
  if (!r2) return null;
  const id = newImageId();
  const bytes = Uint8Array.from(atob(payload.base64), (c) => c.charCodeAt(0));
  try {
    await r2.client.send(new PutObjectCommand({
      Bucket: r2.bucket,
      Key: `ai-images/${id}`,
      Body: bytes,
      ContentType: payload.mimeType,
      CacheControl: "public, max-age=31536000, immutable",
    }));
    return { id };
  } catch (e) {
    console.warn("[ai-image] R2 upload failed:", (e as Error).message);
    return null;
  }
}

export async function getStoredImage(id: string): Promise<{ bytes: Uint8Array; mimeType: string } | null> {
  if (!/^[a-z0-9]{16,64}$/i.test(id)) return null;
  const r2 = r2Client();
  if (!r2) return null;
  try {
    const obj = await r2.client.send(new GetObjectCommand({
      Bucket: r2.bucket,
      Key: `ai-images/${id}`,
    }));
    const bytes = await obj.Body?.transformToByteArray();
    if (!bytes) return null;
    return { bytes, mimeType: obj.ContentType || "image/png" };
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// Main entry

export async function generateMedicalImage(input: GenerateImageInput): Promise<GenerateImageResult> {
  const prompt = buildMedicalImagePrompt(input);
  const aspect = sanitizeAspect(input.aspect);
  const size = sanitizeSize(input.size);

  const cfg = await loadProvidersConfig();
  const gemini = cfg.gemini;
  if (!gemini || !gemini.enabled || !gemini.keys || gemini.keys.length === 0) {
    return {
      ok: false,
      reason: "no_key",
      message: "Image generation needs a Google Gemini API key. Add one in Admin → AI Providers.",
    };
  }

  const models = imageModels();
  // LRU: least recently used key first.
  const keys = [...gemini.keys].sort((a, b) => {
    const ha = hashKey(a);
    const hb = hashKey(b);
    return (keyRuntimeSnapshot("gemini", ha).lastUsedAt || 0) - (keyRuntimeSnapshot("gemini", hb).lastUsedAt || 0);
  });

  const attempts: string[] = [];

  for (const key of keys) {
    const keyHash = hashKey(key);
    if (isKeyCooling("gemini", keyHash)) continue;

    for (const model of models) {
      if (isModelCooling("gemini", keyHash, model)) continue;
      noteRequest("gemini", keyHash);

      let result = await callInteractions(key, model, prompt, aspect, size);
      // A model that the Interactions API doesn't know may still work through
      // the classic generateContent endpoint.
      if (!result.ok && (result.status === 400 || result.status === 404)) {
        result = await callGenerateContent(key, model, prompt, aspect);
      }

      if (result.ok) {
        bumpDailyCounter("gemini", keyHash, 0).catch(() => {});
        const stored = await storeImage(result.payload);
        if (stored) {
          return {
            ok: true,
            url: `/api/ai-image?img=${stored.id}`,
            mimeType: result.payload.mimeType,
            model,
            ms: result.ms,
          };
        }
        return {
          ok: true,
          dataUrl: `data:${result.payload.mimeType};base64,${result.payload.base64}`,
          mimeType: result.payload.mimeType,
          model,
          ms: result.ms,
        };
      }

      attempts.push(`${model}/${result.status}:${result.message.slice(0, 160)}`);
      console.warn(`[ai-image] ${model} key=${keyHash} status=${result.status} msg=${result.message.slice(0, 200)}`);

      if (result.status === 401 || result.status === 403) {
        cool("gemini", keyHash, 24 * 3600_000, "dead", result.message);
        break; // try the next key
      }
      if (result.status === 429) {
        const lower = result.message.toLowerCase();
        if (lower.includes("day") || lower.includes("quota") || lower.includes("daily")) {
          coolModelUntilUTCMidnight("gemini", keyHash, model, "rpd", result.message);
        } else {
          coolModel("gemini", keyHash, model, 60_000, "rpm", result.message);
        }
        continue; // try another model on the same key
      }
      if (result.status >= 500) {
        coolModel("gemini", keyHash, model, 120_000, "5xx", result.message);
        continue;
      }
      // 400/404/other: the key is fine, this model isn't available. Try the
      // next model.
    }
  }

  console.warn(`[ai-image] all attempts failed: ${attempts.slice(-8).join(" | ")}`);
  return {
    ok: false,
    reason: "busy",
    message: "Image generation is unavailable right now. The text explanation is still ready; try the visual again in a moment.",
  };
}
